+const InstanceContentKey = "InstanceID"
+
+// occurrence 0 -> "c-mortgages-repayment"; 1 -> "c-mortgages-repayment-2"
+func InstanceToken(function string, occurrence int) string {
+	s := strings.ToLower(strings.TrimSpace(function))
+	s = strings.Trim(reNotSelectorSafe.ReplaceAllString(s, "-"), "-")
+	if s == "" { s = fmt.Sprintf("anon-%d", occurrence) } // never a bare "c-" shared by all
+	if occurrence <= 0 { return "c-" + s }
+	return fmt.Sprintf("c-%s-%d", s, occurrence+1)
+}
+
+// THE canonical derivation: walked in position order by every path that can see
+// the whole page, so two paths rendering one page agree by construction.
+type InstanceCounter struct{ seen map[string]int }
+func NewInstanceCounter() *InstanceCounter { return &InstanceCounter{seen: map[string]int{}} }
+func (c *InstanceCounter) Next(function string) string {
+	key := strings.ToLower(strings.TrimSpace(function))
+	tok := InstanceToken(function, c.seen[key]); c.seen[key]++; return tok
+}
+func InstanceTokensForPage(functions []string) []string { /* Next over the list */ }
+
+func BindInstanceToken(rc *RenderContext, token string) {
+	if rc == nil { return }
+	if rc.ContentData == nil { rc.ContentData = map[string]interface{}{} }
+	rc.ContentData[InstanceContentKey] = token
+}
+// For a path that renders ONE section and cannot see the page: occurrence 0
+// into the SAME rule. Right wherever the component appears once; where it is
+// wrong the two instances collide, and a collision is what the detector reports.
+func BindSingleSectionInstanceToken(rc *RenderContext, function string) {
+	BindInstanceToken(rc, InstanceToken(function, 0))
+}
